import java.util.*;
record Metric(int requests,int errors,long max){}
public class Main {public static void main(String[] args){Scanner s=new Scanner(System.in);int n=s.nextInt();Map<String,Metric> metrics=new TreeMap<>();for(int i=0;i<n;i++){String service=s.next();int status=s.nextInt();long duration=s.nextLong();Metric old=metrics.getOrDefault(service,new Metric(0,0,0));metrics.put(service,new Metric(old.requests()+1,old.errors()+(status>=400?1:0),Math.max(old.max(),duration)));}metrics.forEach((k,v)->System.out.println(k+" requests="+v.requests()+" errors="+v.errors()+" max="+v.max()));}}
